import { useState, useEffect, useRef } from 'react';
import { usePerception } from '@/lib/perception/context';

/**
 * ShutdownOverlay - The "arcade shutdown" visual effect
 *
 * When awareness mode toggles, plays a brief dim→brighten sequence
 * that creates the feeling of power cutting and restoring.
 *
 * Timing:
 * - 0-200ms: Dim to peak darkness
 * - 200-350ms: Hold at peak
 * - 350-600ms: Brighten back
 * - Cards start animating around 400ms mark
 */
export function ShutdownOverlay() {
  const { awarenessMode } = usePerception();
  const [isAnimating, setIsAnimating] = useState(false);
  const [phase, setPhase] = useState<'idle' | 'dimming' | 'holding' | 'brightening'>('idle');
  const prevModeRef = useRef(awarenessMode);
  const isFirstRender = useRef(true);

  useEffect(() => {
    // Skip animation on initial render
    if (isFirstRender.current) {
      isFirstRender.current = false;
      prevModeRef.current = awarenessMode;
      return;

