  8→
  9→/**
 10→ * NAVIGATION - Sagmeister-informed sizing
 11→ *
 12→ * Typography hierarchy (responsive clamp):
 13→ * - Logo: 19px mobile → 22px desktop (uppercase, tracked)
 14→ * - Nav links: 18px mobile → 21px desktop (uppercase, tracked)
 15→ * - Generous letter-spacing creates presence
 16→ * - Medium weight (500) for refined look vs Sagmeister's bold (700)
 17→ */
 18→
 19→export function Navigation() {
 20→  const [isChatOpen, setIsChatOpen] = useState(false);
 21→  const [isMenuOpen, setIsMenuOpen] = useState(false);
 22→  const [isToolsOpen, setIsToolsOpen] = useState(false);
 23→  const [scrollProgress, setScrollProgress] = useState(0);
 24→  const pathname = usePathname();
 25→
 26→  // Double-click detection for chatbot icon Easter Egg
 27→  const clickCountRef = useRef(0);
 28→  const clickTimerRef = useRef<NodeJS.Timeout | null>(null);
 29→
 30→  // Double-click detection for chatbot icon
 31→  // Single click: open chatbot
 32→  // Double-click: reveal Tools & Downloads overlay (Easter Egg)
 33→  const handleChatbotClick = useCallback(() => {
 34→    clickCountRef.current++;
 35→
 36→    if (clickCountRef.current === 2) {
 37→      // Double-click detected - open Tools overlay (Easter Egg)
 38→      clickCountRef.current = 0;
 39→      if (clickTimerRef.current) {
 40→        clearTimeout(clickTimerRef.current);
 41→        clickTimerRef.current = null;
 42→      }
 43→      setIsToolsOpen(true);
 44→    } else {
 45→      // Wait for potential second click
 46→      clickTimerRef.current = setTimeout(() => {
 47→        if (clickCountRef.current === 1) {
 48→          // Single click - open chatbot normally
 49→          setIsChatOpen(true);
 50→        }
 51→        clickCountRef.current = 0;
 52→      }, 300);
 53→    }
 54→  }, []);
 55→
 56→  // Cleanup timer on unmount
 57→  useEffect(() => {
 58→    return () => {
 59→      if (clickTimerRef.current) {
 60→        clearTimeout(clickTimerRef.current);
 61→      }
 62→    };
 63→  }, []);
 64→
 65→  // Close menu when route changes
 66→  useEffect(() => {
 67→    setIsMenuOpen(false);
 68→  }, [pathname]);
 69→
 70→  const isHomePage = pathname === '/';
 71→  const isProjectPage = pathname?.startsWith('/projects/');
 72→  // Pages with hero reels need transparent navigation
 73→  const hasHeroReel = isHomePage || isProjectPage;
 74→
 75→  // Active state helper - for aria-current accessibility only (no visual change)
 76→  const isActive = (href: string) => {
 77→    if (href === '/') return isHomePage || isProjectPage;
 78→    return pathname?.startsWith(href);
 79→  };
 80→
 81→  // Track scroll for background opacity - MUST match hero reel fade calculations exactly
 82→  // Navigation background fades in as hero video fades out (synchronized)
 83→  useEffect(() => {
 84→    if (!hasHeroReel) return;
 85→
 86→    const handleScroll = () => {
 87→      const scrollY = window.scrollY;
 88→      const viewportHeight = window.innerHeight;
 89→      const heroHeight = viewportHeight * 0.7;
 90→
 91→      let fadeStartScroll: number;
 92→      let fadeRange: number;
 93→
 94→      if (isProjectPage) {
 95→        // ProjectHeroReel calculation: starts at 30% of hero height
 96→        fadeStartScroll = heroHeight * 0.3;
 97→        fadeRange = 300;
 98→      } else {
 99→        // Homepage HeroReel calculation: tied to intro text position
100→        const introPadding = 160;
101→        const textStartPosition = heroHeight + introPadding;
102→        const oneThirdViewport = viewportHeight / 3;
103→        fadeStartScroll = textStartPosition - oneThirdViewport;
104→        fadeRange = 200;
105→      }
106→
107→      const progress = Math.max(0, Math.min((scrollY - fadeStartScroll) / fadeRange, 1));
108→      setScrollProgress(progress);
109→    };
110→
111→    // Run immediately to sync initial state with hero reel
112→    handleScroll();
113→
114→    window.addEventListener('scroll', handleScroll, { passive: true });
115→    return () => window.removeEventListener('scroll', handleScroll);
116→  }, [hasHeroReel, isProjectPage]);
117→
118→  // Navigation text color - uses design system variable
119→  const textColor = 'var(--text-primary)';
120→
121→  return (
122→    <>
123→    <nav
124→      className="fixed top-0 left-0 right-0 w-full"
125→      style={{
126→        // Hero reel pages: transparent → solid on scroll (NO CSS transition - scroll IS the animation)
127→        // Other pages: solid background
128→        backgroundColor: hasHeroReel
129→          ? `rgba(20, 20, 20, ${scrollProgress})`
130→          : '#141414',
131→        zIndex: 100,
132→        // Exclude from page transition scale - nav should only fade, not move
133→        viewTransitionName: 'navigation'
134→      }}
135→    >
136→      {/* Pentagram-style: fixed padding, not dramatic scaling */}
137→      <div
138→        className="mx-auto"
139→        style={{
140→          maxWidth: 'var(--max-content-width)',
141→          paddingTop: '28px',
142→          paddingBottom: '20px'
143→        }}
144→      >
145→        {/* Top row: Name and Nav - baseline aligned */}
146→        <div
147→          className="flex items-baseline justify-between"
148→          style={{
149→            paddingLeft: 'var(--side-padding)',
150→            paddingRight: 'var(--side-padding)'
151→          }}
152→        >
153→          {/* Logo - Responsive scaling: 19px at 768px → 22px at 1400px+ */}
154→          <a
155→            href="/"
156→            className="nav-link transition-all duration-400"
157→            style={{
158→              color: textColor,
159→              fontFamily: 'var(--font-display)',
160→              fontWeight: 500,
161→              letterSpacing: '0.16em',
162→              fontSize: 'clamp(19px, 0.5vw + 15px, 22px)',
163→              textTransform: 'uppercase'
164→            }}
165→          >
166→            Joseph Ibrahim
167→          </a>
168→
169→          {/* Desktop Navigation - responsive scaling maintains spacing ratio */}
170→          <div className="hidden md:flex items-baseline" style={{ gap: 'clamp(24px, 2.5vw, 36px)' }}>
171→            <ul className="flex items-baseline" style={{ gap: 'clamp(20px, 2vw, 28px)' }}>
172→              <li>
173→                <Link
174→                  href="/"
175→                  className="nav-link nav-item-shift transition-all duration-400"
176→                  style={{
177→                    color: textColor,
178→                    fontFamily: 'var(--font-display)',
179→                    fontWeight: 500,
180→                    letterSpacing: '0.10em',
181→                    fontSize: 'clamp(18px, 0.5vw + 14px, 21px)',
182→                    textTransform: 'uppercase'
