 * This function is called ONCE per request to LOCK the model selection
 * before any generation begins. No reactive fallbacks.
 */
function getLockedModel(): { modelId: string; isLocal: boolean } {
  // Priority 1: Anthropic (configured as PRIMARY in .env.example)
  if (process.env.ANTHROPIC_API_KEY) {
    return { modelId: 'anthropic/claude-3-haiku', isLocal: false };
