  if (process.env.OPENAI_API_KEY) {
    return { modelId: 'openai/gpt-4o-mini', isLocal: false };
  }

  // Priority 3: Ollama (local development only)
  // This only works when Ollama is running locally
  return { modelId: 'ollama/nemotron-mini', isLocal: true };
}

