interface VisitorContext {
  archetype: string;
  confidence: number;
}

function buildSystemPrompt(context: string, visitor?: VisitorContext): string {
  const contextPrompts: Record<string, string> = {
    general: PORTFOLIO_CONTEXT,
    technical: PORTFOLIO_CONTEXT + `\n\nFocus on technical details, workflows, and industry-standard practices. Provide specific, practical information about VFX techniques, tools, and processes.`,
    creative: PORTFOLIO_CONTEXT + `\n\nEmphasize creative vision, artistic choices, and the intersection of technology and artistry. Discuss the creative aspects of VFX work.`,
    portfolio: PORTFOLIO_CONTEXT + `\n\nHelp visitors understand Joseph's projects, the techniques used, and his expertise. Be informative but concise, highlighting key achievements.`,
    career: PORTFOLIO_CONTEXT + `\n\nProvide insights about VFX careers, industry trends, and professional development in lighting and technical direction.`
  };

  let basePrompt = contextPrompts[context] || contextPrompts.general;

  // Apply archetype overlay if confidence is sufficient
  // Threshold: 0.5 - don't adapt on weak signal (USD principle: stability)
  if (visitor && visitor.confidence >= 0.5 && visitor.archetype) {
    const overlay = ARCHETYPE_OVERLAYS[visitor.archetype] || '';
    if (overlay) {
      basePrompt += overlay;
    }
  }

  return basePrompt;
}

interface ConversationMessage {
  type: 'bot' | 'user';
  text: string;
}

// =============================================================================
// LOCKED PARAMETERS (ThinkingMachines: Lock before generation)
// =============================================================================

const LOCKED_PARAMS = {
  temperature: 0.7,        // Balanced creativity/consistency
  maxOutputTokens: 500,    // Reasonable for chat responses
  historyLimit: 20,        // Last 20 messages for context
} as const;

export async function POST(request: NextRequest) {
  // =========================================================================
  // PHASE 1: DETECT - Parse request signals
  // =========================================================================
  let body: {
    message?: string;
    messages?: ConversationMessage[];
    stream?: boolean;
    context?: string;
    visitor?: VisitorContext;
  };

  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 });
  }

  const {
    message,
    messages: conversationHistory = [],
    stream = false,
    context = 'general',
    visitor,
  } = body;

  if (!message) {
    return NextResponse.json({ error: 'Message is required' }, { status: 400 });
  }

  // =========================================================================
  // PHASE 2: CASCADE - Route to locked model
  // =========================================================================
  const selectedModel = models[LOCKED_MODEL.modelId];

  if (!selectedModel) {
    // This should never happen if LOCKED_MODEL is valid
    console.error('Locked model not found in models registry:', LOCKED_MODEL.modelId);
    return NextResponse.json({
      error: 'AI service configuration error',
      details: 'No valid model available'
    }, { status: 500 });
  }

  // =========================================================================
  // PHASE 3: LOCK - Lock all parameters before generation
  // =========================================================================
  // System prompt adapts based on visitor archetype (invisible adaptation)
  const systemPrompt = buildSystemPrompt(context, visitor);

  const aiMessages = [
    { role: 'system' as const, content: systemPrompt },
    // Include previous conversation for context (limit enforced by LOCKED_PARAMS)
    ...conversationHistory.slice(-LOCKED_PARAMS.historyLimit).map((msg: ConversationMessage) => ({
      role: (msg.type === 'user' ? 'user' : 'assistant') as 'user' | 'assistant',
      content: msg.text
    })),
    { role: 'user' as const, content: message }
  ];

  // =========================================================================
  // PHASE 4: EXECUTE - Generate with locked params
  // =========================================================================
  try {
    if (stream) {
      const result = await streamText({
        model: selectedModel,
        messages: aiMessages,
        maxOutputTokens: LOCKED_PARAMS.maxOutputTokens,
        temperature: LOCKED_PARAMS.temperature,
      });

      return new Response(result.textStream, {
        headers: {
          'Content-Type': 'text/plain; charset=utf-8',
          'Transfer-Encoding': 'chunked',
          'X-Model-Used': LOCKED_MODEL.modelId,
        }
      });

    } else {
      const result = await generateText({
        model: selectedModel,
        messages: aiMessages,
        maxOutputTokens: LOCKED_PARAMS.maxOutputTokens,
        temperature: LOCKED_PARAMS.temperature,
      });

      return NextResponse.json({
        success: true,
        response: result.text,
        model: LOCKED_MODEL.modelId,
        isLocal: LOCKED_MODEL.isLocal,
        usage: {
          inputTokens: result.usage.inputTokens,
          outputTokens: result.usage.outputTokens,
          totalTokens: (result.usage.inputTokens || 0) + (result.usage.outputTokens || 0)
        }
      });
    }

  } catch (error) {
    // =========================================================================
    // ERROR HANDLING - Log and return graceful error
    // =========================================================================
    console.error('AI Chat error:', {
      model: LOCKED_MODEL.modelId,
      isLocal: LOCKED_MODEL.isLocal,
      error: error instanceof Error ? error.message : 'Unknown error'
    });

    // For local Ollama errors, provide helpful message
    if (LOCKED_MODEL.isLocal) {
      return NextResponse.json({
        error: 'Local AI service unavailable',
        details: 'Ollama server may not be running. Start with: ollama serve',
        model: LOCKED_MODEL.modelId,
      }, { status: 503 });
    }

    return NextResponse.json({
      error: 'AI service temporarily unavailable',
      details: error instanceof Error ? error.message : 'Unknown error',
      model: LOCKED_MODEL.modelId,
    }, { status: 503 });
  }
}

export async function OPTIONS() {
  return new NextResponse(null, {
    status: 200,
    headers: {
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'GET,OPTIONS,PATCH,DELETE,POST,PUT',
      'Access-Control-Allow-Headers': 'X-CSRF-Token, X-Requested-With, Accept, Accept-Version, Content-Length, Content-MD5, Content-Type, Date, X-Api-Version'
    }
  });
}

