186→      const textStartPosition = heroHeightValue + introPadding;
187→      const oneThirdViewport = viewportHeight / 3;
188→      const fadeStartScroll = textStartPosition - oneThirdViewport;
189→
190→      const fadeRange = 200;
191→      const progress = Math.max(0, Math.min((scrollY - fadeStartScroll) / fadeRange, 1));
192→      setScrollProgress(progress);
193→
194→      // Pause/resume with ref tracking for consistency (desktop only)
195→      if (!isMobile) {
196→        const hasScrolledDown = scrollY > 10;
197→
198→        if (hasScrolledDown && !scrolledDownRef.current) {
199→          scrolledDownRef.current = true;
200→          if (playerRef.current && isReadyRef.current) {
201→            playerRef.current.pause().catch(() => {});
202→          }
203→        } else if (!hasScrolledDown && scrolledDownRef.current) {
204→          scrolledDownRef.current = false;
205→          if (playerRef.current && isReadyRef.current) {
206→            playerRef.current.play().catch(() => {});
207→          }
208→        }
209→      }
210→    };
211→
212→    // Run immediately to sync initial state
213→    handleScroll();
214→
215→    window.addEventListener('scroll', handleScroll, { passive: true });
216→    return () => window.removeEventListener('scroll', handleScroll);
217→  }, [isMobile]);
218→
219→  const scrollOpacity = 1 - scrollProgress;
220→  const heroOpacity = heroRevealed ? scrollOpacity : 0;
221→  const heroScale = heroRevealed ? 1 : 1.02;
222→  const transitionDuration = prefersReducedMotion ? '0ms' : '1.2s';
223→  const transitionEasing = 'cubic-bezier(0.16, 1, 0.3, 1)';
