225→  // Transition strategy: opacity only animates during initial reveal, then becomes instant for scroll
226→  // This ensures scroll-driven fade is perfectly synchronized with navigation
227→  const heroTransition = heroRevealed
228→    ? `transform ${transitionDuration} ${transitionEasing}, filter ${transitionDuration} ${transitionEasing}`
229→    : `opacity ${transitionDuration} ${transitionEasing}, transform ${transitionDuration} ${transitionEasing}, filter ${transitionDuration} ${transitionEasing}`;
