  }
  50% {
    opacity: 1;
    transform: scale(1.15);
  }
}

.typing-dot {
  will-change: transform, opacity;
}

/* Chat message entrance */
@keyframes chatMessageIn {
  from {
    opacity: 0;
    transform: translateY(13px);  /* --space-small: 21 / phi */
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.chat-message-enter {
  animation: chatMessageIn 0.3s ease-out forwards;
}

/* ===========================================
   AWARENESS MODE - ARCADE POWER-UP ANIMATIONS
   =========================================== */

/* Screen shutdown effect - dims before power-up */
@keyframes awarenessShutdown {
  0% { opacity: 1; }
  50% { opacity: 0.1; }
  100% { opacity: 0; }
}

/* Arcade power-up effect - flicker then pulse bright */
@keyframes arcadePowerUp {
  0% {
    opacity: 0;
    filter: brightness(0);
    transform: translateY(40px);
  }
