import type Player from '@vimeo/player';

/**
 * HERO REEL - Homepage Autoplay Video
 *
 * Consistency guarantees:
 * 1. Deterministic initialization with timeout (12s max)
 * 2. Clean error handling with fallback to static state
 * 3. Proper cleanup on unmount
 * 4. Scroll-based pause/resume with ref tracking
 * 5. Mobile optimization: static thumbnail only (no video player)
 * 6. Error event listeners for runtime failures
 */

// Timeout for player initialization (12 seconds - supports slow connections)
const INIT_TIMEOUT_MS = 12000;

// Mobile detection hook - touch devices OR narrow viewports
// Returns { isMobile, isReady } to prevent video initialization race condition
function useIsMobile(): { isMobile: boolean; isReady: boolean } {
  const [isMobile, setIsMobile] = useState(true); // Default to mobile (safer)
  const [isReady, setIsReady] = useState(false);

  useEffect(() => {
    const checkMobile = () => {
      const isTouchDevice = 'ontouchstart' in window || navigator.maxTouchPoints > 0;
      const isNarrowViewport = window.innerWidth < 768;
      setIsMobile(isTouchDevice || isNarrowViewport);
    };

    checkMobile();
    setIsReady(true); // Now we know for sure
    window.addEventListener('resize', checkMobile);
    return () => window.removeEventListener('resize', checkMobile);
  }, []);

  return { isMobile, isReady };
}

