      loop: true,
      autoplay: true,
      controls: false,
      background: true,
      responsive: true,
      title: false,
      byline: false,
      portrait: false,
      dnt: true,
      playsinline: true,
      quality: 'auto',
      speed: true,
    };

    const baseUrl = videoHash
      ? `https://vimeo.com/${videoId}/${videoHash}`
      : `https://vimeo.com/${videoId}`;
    const urlWithTime = startTime > 0 ? `${baseUrl}#t=${startTime}s` : baseUrl;

