  1→'use client';
  2→
  3→import { useState, useEffect, useRef, useCallback } from 'react';
  4→import { ChatTypingIndicator } from './ChatTypingIndicator';
  5→import { ChatProjectCard, parseMessageWithProjects } from './ChatProjectCard';
  6→import { usePerception, SensorEventType } from '@/lib/perception/context';
  7→import { analyzeChatMessage } from '@/lib/perception/classifier';
  8→
  9→interface ChatBotProps {
 10→  isOpen: boolean;
 11→  onClose: () => void;
 12→}
 13→
 14→interface Message {
 15→  type: 'bot' | 'user';
 16→  text: string;
 17→  isStreaming?: boolean;
 18→}
 19→
 20→// Contextual quick reply suggestions based on conversation
 21→const INITIAL_SUGGESTIONS = [
 22→  'What makes Joseph different?',
 23→  'Tell me about Cinderella',
 24→  'How does Joseph use AI?',
 25→  'Is Joseph available?'
 26→];
 27→
 28→const FOLLOW_UP_SUGGESTIONS = [
 29→  'Tell me more',
 30→  'Show me another project',
 31→  'What tools does he use?',
 32→  'How can I contact Joseph?'
 33→];
 34→
 35→/**
 36→ * Render markdown-style text with basic formatting
 37→ * Supports: **bold**, *italic*, `code`, and links
 38→ */
 39→function renderFormattedText(text: string): React.ReactNode {
 40→  // Split by formatting patterns
 41→  const parts: React.ReactNode[] = [];
 42→  let remaining = text;
 43→  let key = 0;
 44→
 45→  // Process bold (**text**)
 46→  const boldRegex = /\*\*(.+?)\*\*/g;
 47→  // Process italic (*text*)
 48→  const italicRegex = /(?<!\*)\*(?!\*)(.+?)(?<!\*)\*(?!\*)/g;
 49→  // Process code (`text`)
 50→  const codeRegex = /`(.+?)`/g;
 51→
 52→  // Simple approach: replace patterns with spans
 53→  let processed = remaining
 54→    .replace(boldRegex, '<b>$1</b>')
 55→    .replace(codeRegex, '<code>$1</code>');
 56→
 57→  // Handle italic separately to avoid conflicts with bold
 58→  processed = processed.replace(/(?<!<[^>]*)\*([^*]+)\*(?![^<]*>)/g, '<em>$1</em>');
 59→
 60→  // Convert to React nodes using dangerouslySetInnerHTML for simplicity
 61→  // In production, consider using a proper markdown parser
 62→  return (
 63→    <span
 64→      dangerouslySetInnerHTML={{ __html: processed }}
 65→      style={{
 66→        // Code styling
 67→      }}
 68→    />
 69→  );
 70→}
 71→
 72→/**
 73→ * Render a message with project cards inline
 74→ */
 75→function MessageContent({ text }: { text: string }) {
 76→  const parts = parseMessageWithProjects(text);
 77→
 78→  return (
 79→    <>
 80→      {parts.map((part, index) => {
 81→        if (part.type === 'project') {
 82→          return <ChatProjectCard key={index} slug={part.content} />;
 83→        }
 84→        return (
 85→          <span key={index}>
 86→            {renderFormattedText(part.content)}
 87→          </span>
 88→        );
 89→      })}
 90→    </>
 91→  );
 92→}
 93→
 94→export function ChatBot({ isOpen, onClose }: ChatBotProps) {
 95→  // Get visitor archetype and event recorder from perception system
 96→  const { archetype, confidence, recordEvent } = usePerception();
 97→
 98→  const getInitialMessage = (): string => {
 99→    return "What would you like to know about Joseph's work?";
100→  };
101→
102→  const [messages, setMessages] = useState<Message[]>([
103→    { type: 'bot', text: getInitialMessage() }
104→  ]);
105→  const [inputValue, setInputValue] = useState('');
106→  const [isTyping, setIsTyping] = useState(false);
107→  const [hasConversation, setHasConversation] = useState(false);
108→
109→  // Track timing for response read time calculation
110→  const lastBotResponseTimeRef = useRef<number>(0);
111→  const userMessageCountRef = useRef<number>(0);
112→
113→  const inputRef = useRef<HTMLInputElement>(null);
114→  const messagesEndRef = useRef<HTMLDivElement>(null);
115→  const isMountedRef = useRef(true);
116→  const abortControllerRef = useRef<AbortController | null>(null);
117→
118→  // Track mounted state
119→  useEffect(() => {
120→    isMountedRef.current = true;
121→    return () => {
122→      isMountedRef.current = false;
123→      if (abortControllerRef.current) {
124→        abortControllerRef.current.abort();
125→      }
126→    };
127→  }, []);
128→
129→  // Focus input when chatbot opens
130→  useEffect(() => {
131→    if (isOpen && inputRef.current) {
132→      const focusTimeout = setTimeout(() => {
133→        if (isMountedRef.current && inputRef.current) {
134→          inputRef.current.focus();
135→        }
136→      }, 100);
137→      return () => clearTimeout(focusTimeout);
138→    }
139→  }, [isOpen]);
140→
141→  // Scroll to bottom when new messages arrive
142→  useEffect(() => {
143→    if (messagesEndRef.current) {
144→      messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
145→    }
146→  }, [messages, isTyping]);
147→
148→  // Handle escape key to close
149→  useEffect(() => {
150→    const handleEscape = (e: KeyboardEvent) => {
151→      if (e.key === 'Escape' && isOpen) {
152→        onClose();
153→      }
154→    };
155→    document.addEventListener('keydown', handleEscape);
156→    return () => document.removeEventListener('keydown', handleEscape);
157→  }, [isOpen, onClose]);
158→
159→  // Reset on open
160→  useEffect(() => {
161→    if (isOpen) {
162→      setMessages([{ type: 'bot', text: getInitialMessage() }]);
163→      setInputValue('');
164→      setIsTyping(false);
165→      setHasConversation(false);
166→      // Reset chat tracking for perception system
167→      lastBotResponseTimeRef.current = 0;
168→      userMessageCountRef.current = 0;
169→      if (abortControllerRef.current) {
170→        abortControllerRef.current.abort();
171→        abortControllerRef.current = null;
172→      }
173→      document.body.setAttribute('data-chatbot-open', 'true');
174→    } else {
175→      document.body.removeAttribute('data-chatbot-open');
176→    }
177→  }, [isOpen]);
178→
179→  // Send message to AI and stream response
180→  const sendMessage = useCallback(async (query: string) => {
181→    if (!query.trim() || isTyping) return;
182→
183→    // Record response read time if this isn't the first message
184→    if (lastBotResponseTimeRef.current > 0) {
185→      const responseReadTime = Date.now() - lastBotResponseTimeRef.current;
186→      recordEvent({
187→        timestamp: Date.now(),
188→        type: SensorEventType.CHAT_RESPONSE_READ,
189→        data: {
190→          responseReadTime,
191→        },
192→      });
193→    }
194→
195→    // Analyze the message for behavioral signals
196→    const isFollowUp = userMessageCountRef.current > 0;
197→    const messageAnalysis = analyzeChatMessage(query, isFollowUp);
198→    userMessageCountRef.current++;
199→
200→    // Record the chat message event
201→    recordEvent({
202→      timestamp: Date.now(),
203→      type: SensorEventType.CHAT_MESSAGE,
204→      data: {
205→        messageLength: messageAnalysis.messageLength,
206→        wordCount: messageAnalysis.wordCount,
207→        hasTechnicalTerms: messageAnalysis.hasTechnicalTerms,
208→        isFollowUp: messageAnalysis.isFollowUp,
209→        questionCategory: messageAnalysis.questionCategory,
210→      },
211→    });
212→
213→    // Add user message
214→    const userMessage: Message = { type: 'user', text: query };
215→    setMessages(prev => [...prev, userMessage]);
216→    setInputValue('');
217→    setIsTyping(true);
218→    setHasConversation(true);
219→
220→    // Abort any existing request
221→    if (abortControllerRef.current) {
222→      abortControllerRef.current.abort();
223→    }
224→    abortControllerRef.current = new AbortController();
225→
226→    try {
227→      // Get conversation history (excluding the message we just added)
228→      const conversationHistory = messages.map(m => ({
229→        type: m.type,
230→        text: m.text
231→      }));
232→
233→      // Server handles model selection deterministically based on environment
234→      // (Anthropic in production, Ollama locally)
235→      // Visitor context enables archetype-aware response adaptation
236→      const response = await fetch('/api/ai-chat', {
237→        method: 'POST',
238→        headers: { 'Content-Type': 'application/json' },
239→        body: JSON.stringify({
240→          message: query,
241→          messages: conversationHistory,
242→          stream: true,
243→          context: 'portfolio',
244→          // Perception context for invisible adaptation
245→          visitor: {
246→            archetype: archetype ?? 'unknown',
247→            confidence: confidence ?? 0,
248→          },
249→        }),
250→        signal: abortControllerRef.current.signal
251→      });
252→
253→      if (!response.ok) {
254→        throw new Error(`API error: ${response.status}`);
255→      }
256→
257→      // Add empty bot message that we'll stream into
258→      const botMessageIndex = messages.length + 1; // +1 for user message we just added
259→      setMessages(prev => [...prev, { type: 'bot', text: '', isStreaming: true }]);
260→
261→      // Stream the response
262→      const reader = response.body?.getReader();
263→      if (!reader) throw new Error('No response body');
264→
265→      const decoder = new TextDecoder();
266→      let fullText = '';
267→
268→      while (true) {
269→        const { done, value } = await reader.read();
270→        if (done) break;
271→
272→        const chunk = decoder.decode(value, { stream: true });
273→        fullText += chunk;
274→
275→        // Update the bot message with streamed content
276→        if (isMountedRef.current) {
277→          setMessages(prev => {
278→            const updated = [...prev];
279→            const lastIndex = updated.length - 1;
280→            if (updated[lastIndex]?.type === 'bot') {
281→              updated[lastIndex] = { type: 'bot', text: fullText, isStreaming: true };
282→            }
283→            return updated;
284→          });
285→        }
286→      }
287→
288→      // Mark streaming as complete
289→      if (isMountedRef.current) {
290→        setMessages(prev => {
291→          const updated = [...prev];
292→          const lastIndex = updated.length - 1;
293→          if (updated[lastIndex]?.type === 'bot') {
294→            updated[lastIndex] = { type: 'bot', text: fullText, isStreaming: false };
295→          }
296→          return updated;
297→        });
298→        setIsTyping(false);
299→        // Track when bot response completed (for read time calculation)
300→        lastBotResponseTimeRef.current = Date.now();
301→      }
302→
303→    } catch (error) {
304→      if (error instanceof Error && error.name === 'AbortError') {
305→        // Request was aborted, ignore
306→        return;
307→      }
308→
309→      console.error('Chat error:', error);
310→
311→      // Add fallback error message
312→      if (isMountedRef.current) {
313→        setMessages(prev => [...prev, {
314→          type: 'bot',
315→          text: "I'm having trouble connecting right now. You can reach Joseph directly at jomar.ibrahim@gmail.com for any questions about his work or availability."
316→        }]);
317→        setIsTyping(false);
318→      }
319→    }
320→  }, [messages, isTyping, archetype, confidence, recordEvent]);
321→
322→  // Handle form submit
323→  const handleSubmit = useCallback((e: React.FormEvent) => {
324→    e.preventDefault();
325→    sendMessage(inputValue);
326→  }, [inputValue, sendMessage]);
327→
328→  // Handle quick reply click
329→  const handleQuickReply = useCallback((question: string) => {
330→    if (!isTyping) {
331→      sendMessage(question);
332→    }
333→  }, [isTyping, sendMessage]);
334→
335→  if (!isOpen) return null;
336→
337→  const isInitialState = messages.length === 1 && messages[0].type === 'bot';
338→  const currentSuggestions = hasConversation ? FOLLOW_UP_SUGGESTIONS : INITIAL_SUGGESTIONS;
339→
340→  return (
341→    <div
342→      className="fixed inset-0 flex items-center justify-center"
343→      onClick={onClose}
344→      style={{
345→        backgroundColor: '#141414',
346→        zIndex: 200,
347→        animation: 'chatFadeIn 250ms ease-out'
348→      }}
349→    >
350→      {/* Close button */}
351→      <button
352→        onClick={onClose}
353→        className="absolute top-8 right-8 transition-opacity duration-300"
354→        aria-label="Close"
355→        style={{ opacity: 0.4, zIndex: 10 }}
356→        onMouseEnter={(e) => (e.currentTarget.style.opacity = '1')}
357→        onMouseLeave={(e) => (e.currentTarget.style.opacity = '0.4')}
358→      >
359→        <svg
360→          width="24"
361→          height="24"
362→          viewBox="0 0 24 24"
363→          fill="none"
364→          stroke="currentColor"
365→          strokeWidth="1"
366→          strokeLinecap="round"
367→          style={{ color: 'var(--text-muted)' }}
368→        >
369→          <line x1="18" y1="6" x2="6" y2="18" />
370→          <line x1="6" y1="6" x2="18" y2="18" />
371→        </svg>
372→      </button>
373→
374→      {/* Centered container */}
375→      <div
376→        className="w-full max-w-2xl mx-6 md:mx-8"
377→        onClick={(e) => e.stopPropagation()}
378→        style={{
379→          animation: 'chatSlideUp 350ms cubic-bezier(0.16, 1, 0.3, 1)'
380→        }}
381→      >
382→        {/* Messages area */}
383→        <div
384→          className="overflow-y-auto"
385→          style={{
386→            maxHeight: '60vh',
387→            scrollbarWidth: 'thin',
388→            scrollbarColor: '#2a2a2a transparent'
389→          }}
390→        >
391→          <div style={{ display: 'flex', flexDirection: 'column', gap: '64px' }}>
392→            {messages.map((message, index) => {
393→              const isHeroPrompt = index === 0 && message.type === 'bot' && isInitialState;
394→
395→              return (
396→                <div
397→                  key={index}
398→                  className={index > 0 ? 'chat-message-enter' : ''}
399→                  style={{
400→                    paddingLeft: message.type === 'user' ? '24px' : '0',
401→                    borderLeft: message.type === 'user' ? '1px solid var(--border-subtle)' : 'none'
402→                  }}
403→                >
404→                  {isHeroPrompt ? (
405→                    <h2
406→                      style={{
407→                        color: 'var(--grey-300)',
408→                        fontFamily: 'var(--font-lora)',
409→                        fontWeight: 400,
410→                        fontStyle: 'italic',
411→                        fontSize: 'clamp(32px, 5.5vw, 48px)',
412→                        lineHeight: 1.15,
413→                        letterSpacing: '0.01em'
414→                      }}
415→                    >
416→                      {message.text}
417→                    </h2>
418→                  ) : (
419→                    <>
420→                      {/* Speaker label */}
421→                      <span
422→                        style={{
423→                          display: 'block',
424→                          color: '#5a5a5a',
425→                          fontFamily: 'var(--font-display)',
426→                          fontWeight: 600,
427→                          fontSize: '10px',
428→                          letterSpacing: '0.18em',
429→                          textTransform: 'uppercase',
430→                          marginBottom: '14px'
431→                        }}
432→                      >
433→                        {message.type === 'user' ? 'You' : 'Joseph Ibrahim'}
434→                      </span>
435→                      {/* Message text with rich content */}
436→                      <div
437→                        style={{
438→                          color: message.type === 'user' ? '#7a7a7a' : '#9a9a9a',
439→                          fontFamily: 'var(--font-display)',
440→                          fontWeight: 400,
441→                          fontSize: message.type === 'bot' ? '17px' : '15px',
442→                          lineHeight: 1.75,
443→                          letterSpacing: '0.01em'
444→                        }}
445→                      >
446→                        <MessageContent text={message.text} />
447→                        {message.isStreaming && (
448→                          <span
449→                            style={{
450→                              display: 'inline-block',
451→                              width: '2px',
452→                              height: '1em',
453→                              backgroundColor: '#9a9a9a',
454→                              marginLeft: '2px',
455→                              animation: 'blink 1s step-end infinite'
456→                            }}
457→                          />
458→                        )}
459→                      </div>
460→                    </>
461→                  )}
462→                </div>
463→              );
464→            })}
465→
466→            {/* Typing indicator */}
467→            {isTyping && messages[messages.length - 1]?.type !== 'bot' && (
