  1→import { ImageResponse } from 'next/og';
  2→import { projects } from '@/lib/projects';
  3→import { genAiProjects } from '@/lib/gen-ai-projects';
  4→
  5→export const runtime = 'edge';
  6→export const alt = 'Joseph Ibrahim — Project';
  7→export const size = { width: 1200, height: 630 };
  8→export const contentType = 'image/png';
  9→
 10→const allProjects = [...projects, ...genAiProjects];
 11→
 12→export default async function Image({ params }: { params: Promise<{ slug: string }> }) {
 13→  const { slug } = await params;
 14→  const project = allProjects.find(p => p.slug === slug);
 15→
 16→  if (!project) {
 17→    // Fallback: simple text card
 18→    return new ImageResponse(
 19→      (
 20→        <div style={{ width: '100%', height: '100%', backgroundColor: '#141414', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#666' }}>
 21→          <span style={{ fontSize: '32px' }}>Project Not Found</span>
 22→        </div>
 23→      ),
 24→      { ...size }
 25→    );
 26→  }
 27→
 28→  // Use Vimeo thumbnail as background
 29→  const thumbnailUrl = project.thumbnail || `https://vumbnail.com/${project.videoId}.jpg`;
 30→
 31→  // Load fonts
 32→  const [loraItalic, dmSans] = await Promise.all([
 33→    fetch(new URL('https://fonts.gstatic.com/s/lora/v35/0QI6MX1D_JOuGQbT0gvTJPa787weuxJMkqt8ndeY9Z6JTg.woff2')).then(r => r.arrayBuffer()),
 34→    fetch(new URL('https://fonts.gstatic.com/s/dmsans/v15/rP2Hp2ywxg089UriCZOIHQ.woff2')).then(r => r.arrayBuffer()),
 35→  ]);
 36→
 37→  // Build subtitle from available metadata
 38→  const subtitleParts: string[] = [];
 39→  if (project.client) subtitleParts.push(project.client);
 40→  if (project.studio) subtitleParts.push(project.studio);
 41→  if (project.year) subtitleParts.push(project.year);
 42→  const subtitle = subtitleParts.join('  ·  ');
 43→
 44→  return new ImageResponse(
 45→    (
 46→      <div style={{ width: '100%', height: '100%', backgroundColor: '#141414', display: 'flex', position: 'relative', overflow: 'hidden' }}>
 47→        {/* Project thumbnail background */}
 48→        <img
 49→          src={thumbnailUrl}
 50→          alt=""
 51→          style={{
 52→            position: 'absolute', top: 0, left: 0, width: '100%', height: '100%',
 53→            objectFit: 'cover', opacity: 0.45, filter: 'saturate(0.8) contrast(1.1)',
 54→          }}
 55→        />
 56→
 57→        {/* Gradient overlay — heavier at bottom for text legibility */}
 58→        <div style={{
 59→          position: 'absolute', left: 0, top: 0, width: '100%', height: '100%',
 60→          background: 'linear-gradient(180deg, rgba(20,20,20,0.5) 0%, rgba(20,20,20,0.65) 40%, rgba(20,20,20,0.92) 100%)',
 61→        }} />
 62→
 63→        {/* Text content — bottom-aligned like a film title card */}
 64→        <div style={{
 65→          display: 'flex', flexDirection: 'column', justifyContent: 'flex-end',
 66→          width: '100%', height: '100%', padding: '60px', position: 'relative', zIndex: 10,
 67→        }}>
 68→          {/* Project title */}
 69→          <div style={{
 70→            color: '#f0f0f0', fontFamily: 'Lora', fontStyle: 'italic', fontWeight: 400,
 71→            fontSize: '56px', lineHeight: 1.15, letterSpacing: '0.005em', marginBottom: '16px',
 72→          }}>
 73→            {project.title}
 74→          </div>
 75→
 76→          {/* Client / Studio / Year */}
 77→          {subtitle ? (
 78→            <div style={{
 79→              color: '#999', fontFamily: 'DM Sans', fontWeight: 400,
 80→              fontSize: '22px', lineHeight: 1.4, letterSpacing: '0.03em',
 81→              marginBottom: '8px',
 82→            }}>
 83→              {subtitle}
 84→            </div>
 85→          ) : null}
 86→
 87→          {/* Role */}
 88→          {project.myRole ? (
 89→            <div style={{
 90→              color: '#6a6a6a', fontFamily: 'DM Sans', fontWeight: 400,
 91→              fontSize: '18px', lineHeight: 1.4, letterSpacing: '0.02em',
 92→            }}>
 93→              {project.myRole}
 94→            </div>
 95→          ) : null}
 96→        </div>
 97→
 98→        {/* Site URL — bottom right */}
 99→        <div style={{
100→          position: 'absolute', bottom: '28px', right: '60px',
101→          color: '#4a4a4a', fontFamily: 'DM Sans', fontWeight: 500,
102→          fontSize: '13px', letterSpacing: '0.12em', textTransform: 'uppercase',
103→        }}>
104→          josephibrahim.com
105→        </div>
106→      </div>
107→    ),
108→    {
109→      ...size,
110→      fonts: [
111→        { name: 'Lora', data: loraItalic, style: 'italic' as const, weight: 400 as const },
112→        { name: 'DM Sans', data: dmSans, style: 'normal' as const, weight: 400 as const },
113→      ],
114→    }
115→  );
116→}
