              >
                <line x1="5" y1="12" x2="19" y2="12" />
                <polyline points="12 5 19 12 12 19" />
              </svg>
            </button>
          </div>

          {/* Quick reply suggestions - show when not typing */}
          {!isTyping && (
            <div
              style={{
                marginTop: '48px',
                display: 'flex',
                flexWrap: 'wrap',
                gap: '10px'
              }}
            >
              {currentSuggestions.map((question) => (
                <button
                  key={question}
                  type="button"
                  onClick={() => handleQuickReply(question)}
                  style={{
                    color: '#7a7a7a',
                    fontFamily: 'var(--font-open-sans)',
                    fontWeight: 400,
                    fontSize: '13px',
                    letterSpacing: '0.01em',
                    background: 'rgba(255, 255, 255, 0.03)',
                    border: 'none',
                    borderRadius: '3px',
                    padding: '8px 14px',
                    cursor: 'pointer',
                    transition: 'all 0.2s ease'
                  }}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.background = 'rgba(255, 255, 255, 0.05)';
                    e.currentTarget.style.color = '#9a9a9a';
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.background = 'rgba(255, 255, 255, 0.03)';
                    e.currentTarget.style.color = '#7a7a7a';
                  }}
                >
                  {question}
                </button>
              ))}
            </div>
          )}
        </form>
      </div>

      <style jsx>{`
        @keyframes chatFadeIn {
          from { opacity: 0; }
          to { opacity: 1; }
        }

        @keyframes chatSlideUp {
          from {
            opacity: 0;
            transform: translateY(24px);
          }
          to {
            opacity: 1;
            transform: translateY(0);
          }
        }

        @keyframes blink {
          0%, 100% { opacity: 1; }
          50% { opacity: 0; }
        }

        input::placeholder {
          color: var(--text-dim);
        }

        input:focus {
          outline: none;
        }

        :global(code) {
          background: rgba(255, 255, 255, 0.06);
          padding: 2px 6px;
          border-radius: 3px;
          font-family: monospace;
          font-size: 0.9em;
        }

        :global(b), :global(strong) {
          color: #c0c0c0;
          font-weight: 500;
        }

        :global(em) {
          font-style: italic;
        }
      `}</style>
    </div>
  );
}

