@import "tailwindcss";

/**
 * GOLDEN RATIO DESIGN SYSTEM
 *
 * Spacing follows Fibonacci sequence (approximates φ = 1.618):
 * - 21, 34, 55, 89, 144, 233px
 * - Each value × 1.618 ≈ next value
 *
 * Blends production warmth with Pentagram refinement:
 * - Dark theme with warm amber accent
 * - Golden ratio spacing throughout
 * - Editorial typography with warmth
 * - Refined interactions
 */

:root {
  /* Golden Ratio: φ = 1.618, 1/φ = 0.618 */
  --phi: 1.618;
  --phi-inverse: 0.618;

  /* Fibonacci spacing scale (each × φ ≈ next) */
  --space-xs: 21px;    /* Fibonacci */
  --space-sm: 34px;    /* 21 × 1.618 ≈ 34 */
  --space-md: 55px;    /* 34 × 1.618 ≈ 55 */
  --space-lg: 89px;    /* 55 × 1.618 ≈ 89 */
  --space-xl: 144px;   /* 89 × 1.618 ≈ 144 */
  --space-2xl: 233px;  /* 144 × 1.618 ≈ 233 */

  /* Typography - Helvetica Neue alternative */
  /* Inter: neo-grotesque sans-serif, clean, neutral, screen-optimized */
  --font-display: var(--font-inter), 'Inter', sans-serif;
  --font-body: var(--font-inter), 'Inter', sans-serif;

  /* Color palette - Dark with warm accent */
  --background: #141414;
  --foreground: #b8b8b8;
  --text-primary: #e8e8e8;
  --text-secondary: #8a8a8a;  /* Consolidated from #888888, #8a8a8a */
  --text-muted: #6a6a6a;      /* Consolidated from #666666, #6a6a6a */
  --text-dim: #5a5a5a;        /* NEW: For subtle labels, tags */
  --border: #2a2a2a;
  --border-subtle: #222222;   /* NEW: For subtle dividers */
  --surface: #1a1a1a;         /* NEW: Elevated surface (cards, tags) */
  --accent: #d4a853;          /* Warm gold - refined amber */
  --accent-subtle: rgba(212, 168, 83, 0.15);

  /* ═══════════════════════════════════════════════════════════════
     COLOR HIERARCHY MANTRA
     Information hierarchy = Color hierarchy

     PRIMARY:   --text-primary (#e8e8e8) — Titles, headings, anchors
     SECONDARY: --grey-500 (#7a7a7a)     — Descriptions, body content
     TERTIARY:  --text-dim (#5a5a5a)     — Metadata, labels, footnotes

     Rule: Brighter = more important. Dimmer = supporting context.
     ═══════════════════════════════════════════════════════════════ */

  /* Grey scale - Deterministic (use these, not hex values) */
  --grey-50: #f0f0f0;   /* Brightest text */
  --grey-100: #e8e8e8;  /* Primary text (= --text-primary) — TITLES */
  --grey-200: #c0c0c0;  /* Emphasis text */
  --grey-300: #a0a0a0;  /* Light secondary */
  --grey-400: #8a8a8a;  /* Secondary text (= --text-secondary) */
  --grey-500: #7a7a7a;  /* Medium grey — DESCRIPTIONS */
  --grey-600: #6a6a6a;  /* Muted text (= --text-muted) */
  --grey-700: #5a5a5a;  /* Dim text (= --text-dim) — METADATA */
  --grey-800: #3a3a3a;  /* Separator dots */
  --grey-900: #2a2a2a;  /* Borders (= --border) */

  /* Micro spacing - for elements smaller than Fibonacci scale */
  --space-micro: 4px;   /* Padding inside small elements */
  --space-tiny: 8px;    /* Small gaps */
  --space-small: 13px;  /* 21 / phi ≈ 13 */

  /* Border radius scale - 3 values only */
  --radius-sm: 4px;     /* Tags, buttons, code blocks */
  --radius-md: 6px;     /* Thumbnails, cards */
  --radius-full: 50%;   /* Circles, avatars */

  /* Standardized transitions */
  --transition-fast: 200ms ease-out;
  --transition-base: 300ms ease-out;
  --transition-smooth: 400ms cubic-bezier(0.25, 0.1, 0.25, 1);

  /* Standardized hover opacity */
  --hover-dim: 0.6;
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --font-sans: var(--font-inter);

  /* Golden ratio spacing */
  --spacing-section: var(--space-lg);  /* 89px */
  --spacing-gutter: var(--space-md);   /* 55px */

  /* Layout - balanced width */
  --max-content-width: 1600px;
  --side-padding: clamp(24px, 3vw, 80px);     /* Fluid: scales with viewport */
  --side-padding-md: clamp(34px, 4vw, 100px);  /* Fluid: scales with viewport */
}

/* Typography */
body {
  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-body), -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  font-feature-settings: "kern" 1, "liga" 1, "calt" 1;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1, h2, h3, h4, h5, h6, p {
  margin: 0;
  font-weight: 400;
}

button {
  border: none;
  font: inherit;
  cursor: pointer;
}

html {
  scroll-behavior: smooth;
}

/* ===========================================
   PROJECT CARD INTERACTIONS
   =========================================== */

/* Hover overlay and transitions handled inline in ProjectCard.tsx and VideoThumbnail.tsx */
/* This keeps all visual logic colocated with the component for easier maintenance */

/* ===========================================
   NAVIGATION INTERACTIONS
   =========================================== */

.nav-link {
  position: relative;
  display: inline-block;
  text-decoration: none;
  /* Reversed hover: full opacity by default, dims on hover */
  opacity: 1;
  transition: opacity var(--transition-smooth);
}

@media (hover: hover) and (pointer: fine) {
  .nav-link:hover {
    opacity: var(--hover-dim);
  }
}

/* Section headers - Light table effect */
.section-header-highlight {
  position: relative;
  display: inline-block;
  /* Light table: dimmed by default, reveals on hover */
  opacity: 0.5;
  transition: opacity var(--transition-smooth);
}

@media (hover: hover) and (pointer: fine) {
  .section-header-highlight:hover {
    opacity: 1;
  }
}

.nav-item-shift {
  transition: opacity var(--transition-smooth);
}

/* Button arrow */
.button-arrow-shift {
  display: inline-flex;
  align-items: center;
  gap: var(--space-tiny);
}

.button-arrow {
  transition: transform var(--transition-smooth), opacity var(--transition-smooth);
  opacity: 0.5;
}

@media (hover: hover) and (pointer: fine) {
  .button-arrow-shift:hover .button-arrow {
    transform: translateX(4px);
    opacity: 1;
  }
}

.gpu-accelerated {
  will-change: transform;
  transform: translateZ(0);
  backface-visibility: hidden;
}

/* ===========================================
   ENTRANCE ANIMATIONS
   =========================================== */

@keyframes fadeUp {
  from {
    opacity: 0;
    transform: translateY(21px);  /* Fibonacci */
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.project-card {
  opacity: 0;
  animation: fadeUp 0.7s ease-out forwards;
}

.project-card:nth-child(1) { animation-delay: 0ms; }
.project-card:nth-child(2) { animation-delay: 80ms; }
.project-card:nth-child(3) { animation-delay: 160ms; }
.project-card:nth-child(4) { animation-delay: 240ms; }
.project-card:nth-child(5) { animation-delay: 320ms; }
.project-card:nth-child(6) { animation-delay: 400ms; }

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

.client-strip {
  animation: fadeIn 0.8s ease-out forwards;
  animation-delay: 200ms;
  opacity: 0;
}

/* Scroll indicator */
@keyframes scrollFloat {
  0%, 100% {
    transform: translateY(0);
    opacity: 0.5;
  }
  50% {
    transform: translateY(6px);
    opacity: 0.8;
  }
}

.scroll-chevron {
  animation: scrollFloat 2.8s ease-in-out infinite;
  will-change: transform, opacity;
}

/* Chat typing indicator */
@keyframes typingPulse {
  0%, 100% {
    opacity: 0.3;
    transform: scale(1);
  }
  50% {
    opacity: 1;
    transform: scale(1.15);
  }
}

.typing-dot {
  will-change: transform, opacity;
}

/* Chat message entrance */
@keyframes chatMessageIn {
  from {
    opacity: 0;
    transform: translateY(13px);  /* --space-small: 21 / phi */
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.chat-message-enter {
  animation: chatMessageIn 0.3s ease-out forwards;
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  [aria-live="polite"] {
    transition: none !important;
  }

  .nav-link,
  .project-title h3,
  .section-header-highlight,
  .project-card,
  .nav-item-shift,
  .button-arrow,
  .scroll-chevron,
  .typing-dot,
  .chat-message-enter {
    transition: none !important;
    transform: none !important;
    animation: none !important;
  }
}

/* ===========================================
   FOCUS INDICATORS FOR ACCESSIBILITY
   =========================================== */

/* Focus-visible indicators for keyboard navigation */
:focus-visible {
  outline: 2px solid rgba(255, 255, 255, 0.5);
  outline-offset: 2px;
}

/* Remove focus ring on mouse click, keep for keyboard */
:focus:not(:focus-visible) {
  outline: none;
}

/* ===========================================
   VIEW TRANSITIONS - Cinematic Page Crossfades
   =========================================== */

/*
 * Design philosophy:
 * - Film dissolve feel, not flashy web animation
 * - Content: subtle crossfade with micro-scale for depth
 * - Navigation: fade only (no scale/position change - stays anchored)
 * - Duration: 500ms content, 400ms nav (slow enough to feel intentional)
 * - Easing: ease-in-out for cinematic linear-ish blend
 */

/* Root (main content) transition */
::view-transition-old(root),
::view-transition-new(root) {
  animation-duration: 500ms;
  animation-timing-function: ease-in-out;
}

/* Old page: fade out with slight scale down */
::view-transition-old(root) {
  animation-name: fade-and-scale-out;
}

/* New page: fade in with slight scale up */
::view-transition-new(root) {
  animation-name: fade-and-scale-in;
}

@keyframes fade-and-scale-out {
  from {
    opacity: 1;
    transform: scale(1);
  }
  to {
    opacity: 0;
    transform: scale(0.98);
  }
}

@keyframes fade-and-scale-in {
  from {
    opacity: 0;
    transform: scale(1.02);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

/* Navigation: fade only, no scale (stays anchored) */
::view-transition-old(navigation),
::view-transition-new(navigation) {
  animation-duration: 400ms;
  animation-timing-function: ease-in-out;
}

::view-transition-old(navigation) {
  animation-name: fade-out-only;
}

::view-transition-new(navigation) {
  animation-name: fade-in-only;
}

/* Footer: fade only, no scale (stays anchored) */
::view-transition-old(footer),
::view-transition-new(footer) {
  animation-duration: 400ms;
  animation-timing-function: ease-in-out;
}

::view-transition-old(footer) {
  animation-name: fade-out-only;
}

::view-transition-new(footer) {
  animation-name: fade-in-only;
}

@keyframes fade-out-only {
  from { opacity: 1; }
  to { opacity: 0; }
}

@keyframes fade-in-only {
  from { opacity: 0; }
  to { opacity: 1; }
}

/* Respect reduced motion */
@media (prefers-reduced-motion: reduce) {
  ::view-transition-old(root),
  ::view-transition-new(root),
  ::view-transition-old(navigation),
  ::view-transition-new(navigation),
  ::view-transition-old(footer),
  ::view-transition-new(footer) {
    animation: none !important;
  }
}

'use client';

import { useState, useEffect, useRef, useCallback } from 'react';
import { usePathname } from 'next/navigation';
import Link from 'next/link';
import dynamic from 'next/dynamic';

const ChatBot = dynamic(() => import('./ChatBot').then(mod => ({ default: mod.ChatBot })), {
  ssr: false,
});

const ToolsOverlay = dynamic(() => import('./ToolsOverlay').then(mod => ({ default: mod.ToolsOverlay })), {
  ssr: false,
});

/**
 * NAVIGATION - Sagmeister-informed sizing
 *
 * Typography hierarchy (responsive clamp):
 * - Logo: 19px mobile → 22px desktop (uppercase, tracked)
 * - Nav links: 18px mobile → 21px desktop (uppercase, tracked)
 * - Generous letter-spacing creates presence
 * - Medium weight (500) for refined look vs Sagmeister's bold (700)
 */

export function Navigation() {
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isToolsOpen, setIsToolsOpen] = useState(false);
  const [scrollProgress, setScrollProgress] = useState(0);
  const pathname = usePathname();

  // Double-click detection for chatbot icon Easter Egg
  const clickCountRef = useRef(0);
  const clickTimerRef = useRef<NodeJS.Timeout | null>(null);

  // Double-click detection for chatbot icon
  // Single click: open chatbot
  // Double-click: reveal Tools & Downloads overlay (Easter Egg)
  const handleChatbotClick = useCallback(() => {
    clickCountRef.current++;

    if (clickCountRef.current === 2) {
      // Double-click detected - open Tools overlay (Easter Egg)
      clickCountRef.current = 0;
      if (clickTimerRef.current) {
        clearTimeout(clickTimerRef.current);
        clickTimerRef.current = null;
      }
      setIsToolsOpen(true);
    } else {
      // Wait for potential second click
      clickTimerRef.current = setTimeout(() => {
        if (clickCountRef.current === 1) {
          // Single click - open chatbot normally
          setIsChatOpen(true);
        }
        clickCountRef.current = 0;
      }, 300);
    }
  }, []);

  // Cleanup timer on unmount
  useEffect(() => {
    return () => {
      if (clickTimerRef.current) {
        clearTimeout(clickTimerRef.current);
      }
    };
  }, []);

  // Close menu when route changes
  useEffect(() => {
    setIsMenuOpen(false);
  }, [pathname]);

  const isHomePage = pathname === '/';
  const isProjectPage = pathname?.startsWith('/projects/');
  // Pages with hero reels need transparent navigation
  const hasHeroReel = isHomePage || isProjectPage;

  // Active state helper - for aria-current accessibility only (no visual change)
  const isActive = (href: string) => {
    if (href === '/') return isHomePage || isProjectPage;
    return pathname?.startsWith(href);
  };

  // Track scroll for background opacity - MUST match hero reel fade calculations exactly
  // Navigation background fades in as hero video fades out (synchronized)
  useEffect(() => {
    if (!hasHeroReel) return;

    const handleScroll = () => {
      const scrollY = window.scrollY;
      const viewportHeight = window.innerHeight;
      const heroHeight = viewportHeight * 0.7;

      let fadeStartScroll: number;
      let fadeRange: number;

      if (isProjectPage) {
        // ProjectHeroReel calculation: starts at 30% of hero height
        fadeStartScroll = heroHeight * 0.3;
        fadeRange = 300;
      } else {
        // Homepage HeroReel calculation: tied to intro text position
        const introPadding = 160;
        const textStartPosition = heroHeight + introPadding;
        const oneThirdViewport = viewportHeight / 3;
        fadeStartScroll = textStartPosition - oneThirdViewport;
        fadeRange = 200;
      }

      const progress = Math.max(0, Math.min((scrollY - fadeStartScroll) / fadeRange, 1));
      setScrollProgress(progress);
    };

    // Run immediately to sync initial state with hero reel
    handleScroll();

    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, [hasHeroReel, isProjectPage]);

  // Navigation text color - uses design system variable
  const textColor = 'var(--text-primary)';

  return (
    <>
    <nav
      className="fixed top-0 left-0 right-0 w-full"
      style={{
        // Hero reel pages: transparent → solid on scroll (NO CSS transition - scroll IS the animation)
        // Other pages: solid background
        backgroundColor: hasHeroReel
          ? `rgba(20, 20, 20, ${scrollProgress})`
          : '#141414',
        zIndex: 100,
        // Exclude from page transition scale - nav should only fade, not move
        viewTransitionName: 'navigation'
      }}
    >
      {/* Pentagram-style: fixed padding, not dramatic scaling */}
      <div
        className="mx-auto"
        style={{
          maxWidth: 'var(--max-content-width)',
          paddingTop: '28px',
          paddingBottom: '20px'
        }}
      >
        {/* Top row: Name and Nav - baseline aligned */}
        <div
          className="flex items-baseline justify-between"
          style={{
            paddingLeft: 'var(--side-padding)',
            paddingRight: 'var(--side-padding)'
          }}
        >
          {/* Logo - Responsive scaling: 19px at 768px → 22px at 1400px+ */}
          <a
            href="/"
            className="nav-link transition-opacity duration-400"
            style={{
              color: textColor,
              fontFamily: 'var(--font-display)',
              fontWeight: 500,
              letterSpacing: '0.16em',
              fontSize: 'clamp(19px, 0.5vw + 15px, 22px)',
              textTransform: 'uppercase'
            }}
          >
            Joseph Ibrahim
          </a>

          {/* Desktop Navigation - responsive scaling maintains spacing ratio */}
          <div className="hidden md:flex items-baseline" style={{ gap: 'clamp(24px, 2.5vw, 36px)' }}>
            <ul className="flex items-baseline" style={{ gap: 'clamp(20px, 2vw, 28px)' }}>
              <li>
                <Link
                  href="/"
                  className="nav-link nav-item-shift transition-opacity duration-400"
                  style={{
                    color: textColor,
                    fontFamily: 'var(--font-display)',
                    fontWeight: 500,
                    letterSpacing: '0.10em',
                    fontSize: 'clamp(18px, 0.5vw + 14px, 21px)',
                    textTransform: 'uppercase'
                  }}
                  aria-current={isActive('/') ? 'page' : undefined}
                >
                  Work
                </Link>
              </li>
              {/* GEN AI - temporarily hidden, page still accessible at /gen-ai */}
              <li>
                <Link
                  href="/photo"
                  className="nav-link nav-item-shift transition-opacity duration-400"
                  style={{
                    color: textColor,
                    fontFamily: 'var(--font-display)',
                    fontWeight: 500,
                    letterSpacing: '0.10em',
                    fontSize: 'clamp(18px, 0.5vw + 14px, 21px)',
                    textTransform: 'uppercase'
                  }}
                  aria-current={isActive('/photo') ? 'page' : undefined}
                >
                  Photo
                </Link>
              </li>
              <li>
                <Link
                  href="/process"
                  className="nav-link nav-item-shift transition-opacity duration-400"
                  style={{
                    color: textColor,
                    fontFamily: 'var(--font-display)',
                    fontWeight: 500,
                    letterSpacing: '0.10em',
                    fontSize: 'clamp(18px, 0.5vw + 14px, 21px)',
                    textTransform: 'uppercase'
                  }}
                  aria-current={isActive('/process') ? 'page' : undefined}
                >
                  Process
                </Link>
              </li>
              <li>
                <Link
                  href="/info"
                  className="nav-link nav-item-shift transition-opacity duration-400"
                  style={{
                    color: textColor,
                    fontFamily: 'var(--font-display)',
                    fontWeight: 500,
                    letterSpacing: '0.10em',
                    fontSize: 'clamp(18px, 0.5vw + 14px, 21px)',
                    textTransform: 'uppercase'
                  }}
                  aria-current={isActive('/info') ? 'page' : undefined}
                >
                  About
                </Link>
              </li>
            </ul>

            {/* Chat bubble icon - aligned to top of nav text */}
            {/* Single-click: open chatbot | Double-click: reveal Tools overlay (Easter Egg) */}
            {/* Matches nav-link hover behavior exactly (dims to 40% on hover) */}
            <button
              onClick={handleChatbotClick}
              className="nav-link nav-item-shift transition-opacity duration-400"
              aria-label="Ask about Joe"
              style={{
                alignSelf: 'flex-start',
                marginTop: '5px',
                background: 'transparent',
                border: 'none',
                padding: 0,
                cursor: 'pointer'
              }}
            >
              <svg
                viewBox="0 0 24 24"
                style={{
                  width: '17px',
                  height: '17px'
                }}
              >
                <path
                  d="M20 2H4C2.9 2 2 2.9 2 4v12c0 1.1.9 2 2 2h2v4l5-4h9c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2z"
                  fill={textColor}
                />
              </svg>
            </button>
          </div>

          {/* Mobile: Chat + Hamburger - 44px min touch targets */}
          {/* Single-click: open chatbot | Double-click: reveal Tools overlay (Easter Egg) */}
          <div className="flex md:hidden items-center gap-3">
            <button
              onClick={handleChatbotClick}
              className="nav-link nav-item-shift transition-opacity duration-400"
              aria-label="Ask about Joe"
              style={{
                minWidth: '44px',
                minHeight: '44px',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                background: 'transparent',
                border: 'none',
                padding: '12px',
                margin: '-8px',
                cursor: 'pointer'
              }}
            >
              <svg
                width="20"
                height="20"
                viewBox="0 0 24 24"
              >
                <path
                  d="M20 2H4C2.9 2 2 2.9 2 4v12c0 1.1.9 2 2 2h2v4l5-4h9c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2z"
                  fill={textColor}
                />
              </svg>
            </button>

            {/* Hamburger - 44px min touch target */}
            <button
              onClick={() => setIsMenuOpen(true)}
              className="transition-opacity duration-400 hover:opacity-60 p-3 -m-2"
              aria-label="Open menu"
              style={{ minWidth: '44px', minHeight: '44px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
            >
              <svg
                width="25"
                height="25"
                viewBox="0 0 24 24"
                fill="none"
                stroke={textColor}
                strokeWidth="1"
                strokeLinecap="round"
                className="transition-opacity duration-400"
              >
                <line x1="4" y1="8" x2="20" y2="8" />
                <line x1="4" y1="16" x2="20" y2="16" />
              </svg>
            </button>
          </div>
        </div>

      </div>
    </nav>

    {/* Mobile Menu - Clean overlay */}
    {isMenuOpen && (
      <div
        className="md:hidden fixed inset-0 flex flex-col justify-center items-center"
        style={{
          backgroundColor: '#141414',
          zIndex: 150,
          animation: 'fadeIn 350ms ease-out'
        }}
        onClick={() => setIsMenuOpen(false)}
      >
        {/* Close button - 44px min touch target */}
        <button
          onClick={() => setIsMenuOpen(false)}
          className="absolute top-9 right-6 p-2 transition-opacity duration-400 hover:opacity-60"
          aria-label="Close menu"
          style={{ minWidth: '44px', minHeight: '44px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
        >
          <svg
            width="30"
            height="30"
            viewBox="0 0 24 24"
            fill="none"
            stroke="var(--text-primary)"
            strokeWidth="1"
            strokeLinecap="round"
          >
            <line x1="18" y1="6" x2="6" y2="18" />
            <line x1="6" y1="6" x2="18" y2="18" />
          </svg>
        </button>

        {/* Navigation Links - Mobile menu (responsive sizing) */}
        <nav onClick={(e) => e.stopPropagation()}>
          <ul
            className="flex flex-col items-center gap-8"
            style={{
              fontWeight: 500,
              fontFamily: 'var(--font-display)',
              letterSpacing: '0.10em',
              fontSize: 'clamp(36px, 10vw, 72px)',
              textTransform: 'uppercase'
            }}
          >
            <li>
              <Link
                href="/"
                className="block py-3 px-8 transition-opacity duration-400 hover:opacity-60"
                style={{
                  color: 'var(--text-primary)',
                  minHeight: '44px',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center'
                }}
                onClick={() => setIsMenuOpen(false)}
                aria-current={isActive('/') ? 'page' : undefined}
              >
                Work
              </Link>
            </li>
            {/* GEN AI - temporarily hidden */}
            <li>
              <Link
                href="/photo"
                className="block py-3 px-8 transition-opacity duration-400 hover:opacity-60"
                style={{
                  color: 'var(--text-primary)',
                  minHeight: '44px',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center'
                }}
                onClick={() => setIsMenuOpen(false)}
                aria-current={isActive('/photo') ? 'page' : undefined}
              >
                Photo
              </Link>
            </li>
            <li>
              <Link
                href="/process"
                className="block py-3 px-8 transition-opacity duration-400 hover:opacity-60"
                style={{
                  color: 'var(--text-primary)',
                  minHeight: '44px',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center'
                }}
                onClick={() => setIsMenuOpen(false)}
                aria-current={isActive('/process') ? 'page' : undefined}
              >
                Process
              </Link>
            </li>
            <li>
              <Link
                href="/info"
                className="block py-3 px-8 transition-opacity duration-400 hover:opacity-60"
                style={{
                  color: 'var(--text-primary)',
                  minHeight: '44px',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center'
                }}
                onClick={() => setIsMenuOpen(false)}
                aria-current={isActive('/info') ? 'page' : undefined}
              >
                About
              </Link>
            </li>
          </ul>
        </nav>
      </div>
    )}

    {/* ChatBot Overlay */}
    <ChatBot isOpen={isChatOpen} onClose={() => setIsChatOpen(false)} />

    {/* Tools & Downloads Overlay (Easter Egg - double-click chat icon) */}
    <ToolsOverlay isOpen={isToolsOpen} onClose={() => setIsToolsOpen(false)} />

    <style jsx>{`
      @keyframes fadeIn {
        from {
          opacity: 0;
        }
        to {
          opacity: 1;
        }
      }
    `}</style>
    </>
  );
}

