    // Wait for mobile detection to complete before deciding
    if (!isMobileReady) return;

    // Skip player initialization on mobile - use static thumbnail instead
    if (isMobile) return;

    if (!containerRef.current) return;

    const baseConfig = {
      muted: true,
      loop: true,
      autoplay: true,
      controls: false,
      background: true,
      responsive: true,
      title: false,
      byline: false,
      portrait: false,
      dnt: true,
      playsinline: true,
      quality: 'auto',
      speed: true,
    };

